// The Apartment scope represents the complete apartment model. Its metrics are
// the combined work-area groups from every apartment scope (including repeated
// scope instances such as multiple bedrooms or bathrooms).
const apartmentCombinedMetricGroups = ['Bed Room', 'Living Room', 'Kitchen', 'Bathroom', 'Kitchen Counter', 'Cup Board']
    .reduce((groups, scopeName) => {
    const sourceGroups = apartmentMetricGroups[scopeName] || [];
    sourceGroups.forEach(sourceGroup => {
        const targetGroup = groups.find(group => group.title === sourceGroup.title);
        if (targetGroup) {
            targetGroup.metrics = targetGroup.metrics.concat(sourceGroup.metrics);
        }
        else {
            groups.push({ title: sourceGroup.title, metrics: sourceGroup.metrics.slice() });
        }
    });
    return groups;
}, []);
apartmentMetricGroups.Apartment = apartmentCombinedMetricGroups;
const flattenMetricGroups = (scope) => apartmentMetricGroups[scope].reduce((metrics, group) => metrics.concat(group.metrics), []);
